    try testing.expectEqualStrings("CET", abbrevAt(pr, far + 180 * 86400));
    try testing.expectEqualStrings("IST", abbrevAt(find("Asia/Kolkata").?, 1721044800));
    // tzdata names with no letters: `<+05>-5` -> "+05", also in the footer era.
