    // A zone built by hand: footer parsed per call, table states unnamed.
    const z = Zone{ .name = "Test/abbr", .init_off = 0, .init_dst = false, .trans = &.{}, .posix = "<-03>3<-02>,M3.5.0/-2,M10.5.0/-1" };
